CREATE OR REPLACE FUNCTION public.is_valid_phone_e164(_phone text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE _digits text; _national text; _plans jsonb; _plan jsonb; _type jsonb; _calling_code_length integer;
BEGIN
  IF _phone IS NULL OR _phone !~ '^\+[1-9][0-9]{6,14}$' THEN RETURN false; END IF;
  _digits := substring(_phone FROM 2);
  FOR _size IN 1..3 LOOP
    _plans := public._phone_numbering_plans(left(_digits, _size));
    IF _plans IS NOT NULL THEN _calling_code_length := _size; EXIT; END IF;
  END LOOP;
  IF _plans IS NULL THEN RETURN false; END IF;
  _national := substring(_digits FROM _calling_code_length + 1);
  FOR _plan IN SELECT value FROM jsonb_array_elements(_plans) LOOP
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(_plan->'lengths') l(value) WHERE value::integer = length(_national))
      OR _national !~ ('^(?:' || (_plan->>'pattern') || ')$') THEN CONTINUE; END IF;
    IF jsonb_array_length(_plan->'types') = 0 THEN RETURN true; END IF;
    FOR _type IN SELECT value FROM jsonb_array_elements(_plan->'types') LOOP
      IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(_type->'lengths') l(value) WHERE value::integer = length(_national))
        AND _national ~ ('^(?:' || (_type->>'pattern') || ')$') THEN RETURN true; END IF;
    END LOOP;
  END LOOP;
  RETURN false;
END;
$function$;

CREATE OR REPLACE FUNCTION public.phone_to_e164(_phone text, _country text DEFAULT 'BR'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH input AS (
    SELECT btrim(COALESCE(_phone, '')) AS raw,
      regexp_replace(COALESCE(_phone, ''), '\D', '', 'g') AS digits
  )
  , candidate AS (SELECT CASE
    WHEN raw = '' OR raw !~ '^\+?[0-9() .-]+$' THEN NULL
    WHEN raw LIKE '+%' AND digits ~ '^[1-9][0-9]{6,14}$' THEN '+' || digits
    WHEN upper(COALESCE(_country, 'BR')) = 'BR' AND digits ~ '^[1-9][0-9]9?[0-9]{8}$'
      THEN '+55' || digits
    WHEN upper(COALESCE(_country, 'BR')) = 'BR' AND digits ~ '^55[1-9][0-9]9?[0-9]{8}$'
      THEN '+' || digits
    ELSE NULL
  END AS value FROM input)
  SELECT CASE WHEN public.is_valid_phone_e164(value) THEN value ELSE NULL END FROM candidate;
$function$;

CREATE OR REPLACE FUNCTION public.phone_stored_identity_digits(_e164 text, _raw text, _country text DEFAULT 'BR'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH input AS (
    SELECT COALESCE(NULLIF(btrim(_e164), ''), btrim(COALESCE(_raw, ''))) AS raw,
      substring(COALESCE(public.phone_to_e164(_e164, 'ZZ'), public.phone_to_e164(_raw, _country)) FROM 2) AS canonical
  ), digits AS (
    SELECT *, regexp_replace(raw, '\D', '', 'g') AS value FROM input
  )
  SELECT COALESCE(canonical, CASE
    WHEN upper(COALESCE(_country, 'BR')) <> 'BR' OR raw !~ '^\+?[0-9() .-]+$' THEN NULL
    WHEN raw LIKE '+%' AND value ~ '^55[1-9][0-9](9?[0-9]{8})$' THEN value
    WHEN raw NOT LIKE '+%' AND value ~ '^[1-9][0-9](9?[0-9]{8})$' THEN '55' || value
    WHEN raw NOT LIKE '+%' AND value ~ '^55[1-9][0-9](9?[0-9]{8})$' THEN value
    ELSE NULL
  END) FROM digits;
$function$;

CREATE OR REPLACE FUNCTION public.phone_identity_digits(_e164 text, _raw text, _country text DEFAULT 'BR'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.phone_stored_identity_digits(_e164, _raw, _country);
$function$;

CREATE OR REPLACE FUNCTION public.phone_customer_identity_digits(_e164 text, _raw text, _country text DEFAULT 'BR'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH input AS (
    SELECT regexp_replace(COALESCE(_raw, ''), '\D', '', 'g') AS digits,
      public.phone_identity_digits(_e164, _raw, _country) AS canonical
  )
  SELECT COALESCE(canonical, CASE
    WHEN upper(COALESCE(_country, 'BR')) <> 'BR' OR digits = '' THEN NULL
    WHEN digits !~ '^55' AND length(digits) <= 11 THEN '55' || digits
    ELSE digits
  END) FROM input;
$function$;

CREATE OR REPLACE FUNCTION public.normalize_whatsapp_phone(_phone text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT substring(public.phone_to_e164(_phone, 'BR') FROM 2);
$function$;

CREATE OR REPLACE FUNCTION public.canonical_crm_customer_key(_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE WHEN btrim(_key) ~ '^phone:55[0-9]{8,9}$'
      AND public.phone_stored_identity_digits(NULL, substring(btrim(_key) FROM 7), 'BR') IS NOT NULL
    THEN 'phone:55' || substring(btrim(_key) FROM 7) ELSE btrim(_key) END;
$function$;

CREATE OR REPLACE FUNCTION public._is_valid_iana_time_zone(_time_zone text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_timezone_names names
    WHERE names.name = NULLIF(btrim(_time_zone), '')
  );
$function$;

CREATE OR REPLACE FUNCTION public._company_report_time_zone(_company_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _time_zone text;
BEGIN
  SELECT companies.time_zone
  INTO _time_zone
  FROM public.companies
  WHERE companies.id = _company_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Empresa não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public._is_valid_iana_time_zone(_time_zone) THEN
    RAISE EXCEPTION 'Fuso horário inválido para a empresa.' USING ERRCODE = '22023';
  END IF;

  RETURN _time_zone;
END;
$function$;

CREATE OR REPLACE FUNCTION public._crm_phone_state_code(_phone_normalized text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH phone AS (
    SELECT regexp_replace(COALESCE(_phone_normalized, ''), '\D', '', 'g') AS digits
  ),
  ddd AS (
    SELECT CASE
      WHEN digits LIKE '55%' AND length(digits) IN (12, 13) THEN substring(digits FROM 3 FOR 2)
      WHEN false THEN NULL::text
      ELSE NULL
    END AS value
    FROM phone
  )
  SELECT CASE
    WHEN value = ANY (ARRAY['11','12','13','14','15','16','17','18','19']) THEN 'SP'
    WHEN value = ANY (ARRAY['21','22','24']) THEN 'RJ'
    WHEN value = ANY (ARRAY['27','28']) THEN 'ES'
    WHEN value = ANY (ARRAY['31','32','33','34','35','37','38']) THEN 'MG'
    WHEN value = ANY (ARRAY['41','42','43','44','45','46']) THEN 'PR'
    WHEN value = ANY (ARRAY['47','48','49']) THEN 'SC'
    WHEN value = ANY (ARRAY['51','53','54','55']) THEN 'RS'
    WHEN value = '61' THEN 'DF'
    WHEN value = ANY (ARRAY['62','64']) THEN 'GO'
    WHEN value = ANY (ARRAY['65','66']) THEN 'MT'
    WHEN value = '67' THEN 'MS'
    WHEN value = '68' THEN 'AC'
    WHEN value = '69' THEN 'RO'
    WHEN value = ANY (ARRAY['92','97']) THEN 'AM'
    WHEN value = '95' THEN 'RR'
    WHEN value = ANY (ARRAY['91','93','94']) THEN 'PA'
    WHEN value = '96' THEN 'AP'
    WHEN value = '63' THEN 'TO'
    WHEN value = ANY (ARRAY['98','99']) THEN 'MA'
    WHEN value = ANY (ARRAY['86','89']) THEN 'PI'
    WHEN value = ANY (ARRAY['85','88']) THEN 'CE'
    WHEN value = '84' THEN 'RN'
    WHEN value = '83' THEN 'PB'
    WHEN value = ANY (ARRAY['81','87']) THEN 'PE'
    WHEN value = '82' THEN 'AL'
    WHEN value = '79' THEN 'SE'
    WHEN value = ANY (ARRAY['71','73','74','75','77']) THEN 'BA'
    ELSE NULL
  END
  FROM ddd;
$function$;

CREATE OR REPLACE FUNCTION public._crm_state_name(_state_code text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE upper(COALESCE(_state_code, ''))
    WHEN 'AC' THEN 'Acre'
    WHEN 'AL' THEN 'Alagoas'
    WHEN 'AP' THEN 'Amapá'
    WHEN 'AM' THEN 'Amazonas'
    WHEN 'BA' THEN 'Bahia'
    WHEN 'CE' THEN 'Ceará'
    WHEN 'DF' THEN 'Distrito Federal'
    WHEN 'ES' THEN 'Espírito Santo'
    WHEN 'GO' THEN 'Goiás'
    WHEN 'MA' THEN 'Maranhão'
    WHEN 'MT' THEN 'Mato Grosso'
    WHEN 'MS' THEN 'Mato Grosso do Sul'
    WHEN 'MG' THEN 'Minas Gerais'
    WHEN 'PA' THEN 'Pará'
    WHEN 'PB' THEN 'Paraíba'
    WHEN 'PR' THEN 'Paraná'
    WHEN 'PE' THEN 'Pernambuco'
    WHEN 'PI' THEN 'Piauí'
    WHEN 'RJ' THEN 'Rio de Janeiro'
    WHEN 'RN' THEN 'Rio Grande do Norte'
    WHEN 'RS' THEN 'Rio Grande do Sul'
    WHEN 'RO' THEN 'Rondônia'
    WHEN 'RR' THEN 'Roraima'
    WHEN 'SC' THEN 'Santa Catarina'
    WHEN 'SP' THEN 'São Paulo'
    WHEN 'SE' THEN 'Sergipe'
    WHEN 'TO' THEN 'Tocantins'
    ELSE NULL
  END;
$function$;

CREATE OR REPLACE FUNCTION public._get_crm_contact_records(_company_id uuid)
 RETURNS TABLE(company_id uuid, customer_key text, identity_kind text, identity_value text, canonical_event_key text, contact_record_key text, visit_id uuid, contact_id uuid, visit_origin text, lead_source text, role_kind text, record_date date, record_time time without time zone, record_at timestamp with time zone, presence_date date, presence_time time without time zone, presence_at timestamp with time zone, contact_created_at timestamp with time zone, guest_name text, guest_phone text, guest_email text, guest_birthdate date, phone_normalized text, email_normalized text, party_size integer, status text, normalized_status text, occasion text, origin_waitlist_id uuid, came_from_waitlist boolean, reservation_holder_name text, is_waitlist_suppressed boolean, is_canonical_presence boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH report_context AS MATERIALIZED (
    SELECT public._company_report_time_zone(_company_id) AS time_zone
  ),
  raw_records AS (
    SELECT
      reservations.company_id,
      'reservation:' || reservations.id::text AS canonical_event_key,
      'reservation_holder:' || reservations.id::text AS contact_record_key,
      reservations.id AS visit_id,
      reservations.id AS contact_id,
      'reservation'::text AS visit_origin,
      'reservation_holder'::text AS lead_source,
      'holder'::text AS role_kind,
      reservations.date AS record_date,
      reservations.time AS record_time,
      (reservations.date + reservations.time) AT TIME ZONE report_context.time_zone AS record_at,
      COALESCE(
        (reservations.checked_in_at AT TIME ZONE report_context.time_zone)::date,
        reservations.date
      ) AS presence_date,
      COALESCE(
        (reservations.checked_in_at AT TIME ZONE report_context.time_zone)::time,
        reservations.time
      ) AS presence_time,
      COALESCE(
        reservations.checked_in_at,
        (reservations.date + reservations.time) AT TIME ZONE report_context.time_zone
      ) AS presence_at,
      reservations.created_at AS contact_created_at,
      NULLIF(btrim(reservations.guest_name), '') AS guest_name,
      NULLIF(btrim(reservations.guest_phone), '') AS guest_phone,
      NULLIF(lower(btrim(reservations.guest_email)), '') AS guest_email,
      reservations.guest_birthdate AS guest_birthdate,
      public.phone_customer_identity_digits(reservations.guest_phone_e164, reservations.guest_phone, reservations.guest_phone_country) AS phone_normalized,
      NULLIF(lower(btrim(reservations.guest_email)), '') AS email_normalized,
      COALESCE(reservations.checked_in_party_size, reservations.party_size) AS party_size,
      reservations.status,
      CASE
        WHEN lower(btrim(reservations.status)) IN ('checked_in', 'completed') THEN 'checked_in'
        WHEN lower(btrim(reservations.status)) IN ('no-show', 'no_show') THEN 'no-show'
        WHEN lower(btrim(reservations.status)) IN (
          'pending_payment',
          'cancelled',
          'payment_expired',
          'payment_cancelled',
          'paid_after_expiration'
        ) THEN lower(btrim(reservations.status))
        ELSE 'confirmed'
      END AS normalized_status,
      reservations.occasion,
      reservations.origin_waitlist_id,
      reservations.origin_waitlist_id IS NOT NULL AS came_from_waitlist,
      NULLIF(btrim(reservations.guest_name), '') AS reservation_holder_name,
      1 AS contact_priority,
      0 AS contact_position,
      false AS is_waitlist_suppressed,
      lower(btrim(reservations.status)) IN ('checked_in', 'completed') AS is_canonical_presence
    FROM public.reservations
    CROSS JOIN report_context
    WHERE reservations.company_id = _company_id

    UNION ALL

    SELECT
      reservations.company_id,
      'reservation:' || reservations.id::text,
      'reservation_companion:' || reservation_companions.id::text,
      reservations.id,
      reservation_companions.id,
      'reservation',
      'reservation_companion',
      'companion',
      reservations.date,
      reservations.time,
      (reservations.date + reservations.time) AT TIME ZONE report_context.time_zone,
      COALESCE(
        (reservations.checked_in_at AT TIME ZONE report_context.time_zone)::date,
        reservations.date
      ),
      COALESCE(
        (reservations.checked_in_at AT TIME ZONE report_context.time_zone)::time,
        reservations.time
      ),
      COALESCE(
        reservations.checked_in_at,
        (reservations.date + reservations.time) AT TIME ZONE report_context.time_zone
      ),
      reservation_companions.created_at,
      NULLIF(btrim(reservation_companions.name), ''),
      NULLIF(btrim(reservation_companions.phone), ''),
      NULLIF(lower(btrim(reservation_companions.email)), ''),
      reservation_companions.birthdate,
      public.phone_customer_identity_digits(reservation_companions.phone_e164, reservation_companions.phone, reservation_companions.phone_country),
      NULLIF(lower(btrim(reservation_companions.email)), ''),
      COALESCE(reservations.checked_in_party_size, reservations.party_size),
      reservations.status,
      CASE
        WHEN lower(btrim(reservations.status)) IN ('checked_in', 'completed') THEN 'checked_in'
        WHEN lower(btrim(reservations.status)) IN ('no-show', 'no_show') THEN 'no-show'
        WHEN lower(btrim(reservations.status)) IN (
          'pending_payment',
          'cancelled',
          'payment_expired',
          'payment_cancelled',
          'paid_after_expiration'
        ) THEN lower(btrim(reservations.status))
        ELSE 'confirmed'
      END,
      reservations.occasion,
      reservations.origin_waitlist_id,
      reservations.origin_waitlist_id IS NOT NULL,
      NULLIF(btrim(reservations.guest_name), ''),
      2,
      reservation_companions.position,
      false,
      lower(btrim(reservations.status)) IN ('checked_in', 'completed')
    FROM public.reservation_companions
    JOIN public.reservations
      ON reservations.id = reservation_companions.reservation_id
    CROSS JOIN report_context
    WHERE reservations.company_id = _company_id

    UNION ALL

    SELECT
      waitlist.company_id,
      'waitlist:' || waitlist.id::text,
      'waitlist_holder:' || waitlist.id::text,
      waitlist.id,
      waitlist.id,
      'waitlist',
      'waitlist_holder',
      'holder',
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::date,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::date
      ),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::time,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::time
      ),
      COALESCE(waitlist.seated_at, waitlist.created_at),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::date,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::date
      ),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::time,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::time
      ),
      COALESCE(waitlist.seated_at, waitlist.created_at),
      waitlist.created_at,
      NULLIF(btrim(waitlist.guest_name), ''),
      NULLIF(btrim(waitlist.guest_phone), ''),
      NULLIF(lower(btrim(waitlist.guest_email)), ''),
      waitlist.guest_birthdate,
      public.phone_customer_identity_digits(waitlist.guest_phone_e164, waitlist.guest_phone, waitlist.guest_phone_country),
      NULLIF(lower(btrim(waitlist.guest_email)), ''),
      COALESCE(waitlist.seated_party_size, waitlist.party_size),
      waitlist.status,
      'checked_in',
      NULL::text,
      NULL::uuid,
      true,
      NULLIF(btrim(waitlist.guest_name), ''),
      1,
      0,
      linkage.has_linked_presence,
      NOT linkage.has_linked_presence
    FROM public.waitlist
    CROSS JOIN report_context
    CROSS JOIN LATERAL (
      SELECT EXISTS (
        SELECT 1
        FROM public.reservations linked_reservation
        WHERE linked_reservation.origin_waitlist_id = waitlist.id
          AND linked_reservation.status IN ('checked_in', 'completed')
      ) AS has_linked_presence
    ) AS linkage
    WHERE waitlist.company_id = _company_id
      AND waitlist.status = 'seated'

    UNION ALL

    SELECT
      waitlist.company_id,
      'waitlist:' || waitlist.id::text,
      'waitlist_companion:' || waitlist_companions.id::text,
      waitlist.id,
      waitlist_companions.id,
      'waitlist',
      'waitlist_companion',
      'companion',
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::date,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::date
      ),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::time,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::time
      ),
      COALESCE(waitlist.seated_at, waitlist.created_at),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::date,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::date
      ),
      COALESCE(
        (waitlist.seated_at AT TIME ZONE report_context.time_zone)::time,
        (waitlist.created_at AT TIME ZONE report_context.time_zone)::time
      ),
      COALESCE(waitlist.seated_at, waitlist.created_at),
      waitlist_companions.created_at,
      NULLIF(btrim(waitlist_companions.name), ''),
      NULLIF(btrim(waitlist_companions.phone), ''),
      NULLIF(lower(btrim(waitlist_companions.email)), ''),
      waitlist_companions.birthdate,
      public.phone_customer_identity_digits(waitlist_companions.phone_e164, waitlist_companions.phone, waitlist_companions.phone_country),
      NULLIF(lower(btrim(waitlist_companions.email)), ''),
      COALESCE(waitlist.seated_party_size, waitlist.party_size),
      waitlist.status,
      'checked_in',
      NULL::text,
      NULL::uuid,
      true,
      NULLIF(btrim(waitlist.guest_name), ''),
      2,
      waitlist_companions.position,
      linkage.has_linked_presence,
      NOT linkage.has_linked_presence
    FROM public.waitlist_companions
    JOIN public.waitlist
      ON waitlist.id = waitlist_companions.waitlist_id
    CROSS JOIN report_context
    CROSS JOIN LATERAL (
      SELECT EXISTS (
        SELECT 1
        FROM public.reservations linked_reservation
        WHERE linked_reservation.origin_waitlist_id = waitlist.id
          AND linked_reservation.status IN ('checked_in', 'completed')
      ) AS has_linked_presence
    ) AS linkage
    WHERE waitlist.company_id = _company_id
      AND waitlist.status = 'seated'
  ),
  labeled_records AS (
    SELECT
      raw_records.*,
      CASE
        WHEN raw_records.phone_normalized IS NOT NULL
          THEN 'phone:' || raw_records.phone_normalized
        WHEN raw_records.email_normalized IS NOT NULL
          THEN 'email:' || raw_records.email_normalized
        ELSE 'contact:' || raw_records.lead_source || ':' || raw_records.contact_id::text
      END AS customer_key,
      CASE
        WHEN raw_records.phone_normalized IS NOT NULL THEN 'phone'
        WHEN raw_records.email_normalized IS NOT NULL THEN 'email'
        ELSE 'contact'
      END AS identity_kind,
      CASE
        WHEN raw_records.phone_normalized IS NOT NULL THEN raw_records.phone_normalized
        WHEN raw_records.email_normalized IS NOT NULL THEN raw_records.email_normalized
        ELSE raw_records.lead_source || ':' || raw_records.contact_id::text
      END AS identity_value
    FROM raw_records
  ),
  ranked_records AS (
    SELECT
      labeled_records.*,
      row_number() OVER (
        PARTITION BY
          labeled_records.company_id,
          labeled_records.canonical_event_key,
          labeled_records.customer_key
        ORDER BY
          labeled_records.contact_priority,
          labeled_records.contact_position,
          labeled_records.contact_id
      ) AS event_contact_rank
    FROM labeled_records
  )
  SELECT
    ranked_records.company_id,
    ranked_records.customer_key,
    ranked_records.identity_kind,
    ranked_records.identity_value,
    ranked_records.canonical_event_key,
    ranked_records.contact_record_key,
    ranked_records.visit_id,
    ranked_records.contact_id,
    ranked_records.visit_origin,
    ranked_records.lead_source,
    ranked_records.role_kind,
    ranked_records.record_date,
    ranked_records.record_time,
    ranked_records.record_at,
    ranked_records.presence_date,
    ranked_records.presence_time,
    ranked_records.presence_at,
    ranked_records.contact_created_at,
    ranked_records.guest_name,
    ranked_records.guest_phone,
    ranked_records.guest_email,
    ranked_records.guest_birthdate,
    ranked_records.phone_normalized,
    ranked_records.email_normalized,
    ranked_records.party_size,
    ranked_records.status,
    ranked_records.normalized_status,
    ranked_records.occasion,
    ranked_records.origin_waitlist_id,
    ranked_records.came_from_waitlist,
    ranked_records.reservation_holder_name,
    ranked_records.is_waitlist_suppressed,
    ranked_records.is_canonical_presence
  FROM ranked_records
  WHERE ranked_records.event_contact_rank = 1;
$function$;

CREATE OR REPLACE FUNCTION public._get_crm_lead_profiles(_company_id uuid)
 RETURNS TABLE(company_id uuid, customer_key text, identity_kind text, identity_value text, phone_normalized text, email_normalized text, display_phone text, latest_name text, latest_email text, latest_birthdate date, first_seen_at timestamp with time zone, last_visit_date date, last_visit_time time without time zone, last_visit_at timestamp with time zone, state_code text, state_name text, source text, canonical_visit_count integer, crm_lead_id uuid, crm_notes text, crm_imported_at timestamp with time zone, crm_imported_by_user_id uuid, crm_import_filename text, is_import_only boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH contact_records AS MATERIALIZED (
    SELECT *
    FROM public._get_crm_contact_records(_company_id)
  ),
  contact_first_seen AS (
    SELECT
      contact_records.company_id,
      contact_records.customer_key,
      min(contact_records.contact_created_at) AS first_seen_at
    FROM contact_records
    GROUP BY
      contact_records.company_id,
      contact_records.customer_key
  ),
  visible_contact_rollup AS (
    SELECT
      contact_records.company_id,
      contact_records.customer_key,
      min(contact_records.identity_kind) AS identity_kind,
      min(contact_records.identity_value) AS identity_value,
      min(contact_records.phone_normalized) AS phone_normalized,
      min(contact_records.email_normalized) FILTER (
        WHERE contact_records.email_normalized IS NOT NULL
      ) AS email_normalized,
      (
        array_agg(
          contact_records.guest_phone
          ORDER BY
            contact_records.record_at DESC,
            CASE contact_records.role_kind WHEN 'holder' THEN 1 ELSE 2 END,
            contact_records.contact_record_key
        ) FILTER (
          WHERE NULLIF(btrim(contact_records.guest_phone), '') IS NOT NULL
        )
      )[1] AS display_phone,
      (
        array_agg(
          contact_records.guest_name
          ORDER BY
            contact_records.record_at DESC,
            CASE contact_records.role_kind WHEN 'holder' THEN 1 ELSE 2 END,
            contact_records.contact_record_key
        ) FILTER (
          WHERE NULLIF(btrim(contact_records.guest_name), '') IS NOT NULL
        )
      )[1] AS latest_name,
      (
        array_agg(
          contact_records.guest_email
          ORDER BY
            contact_records.record_at DESC,
            CASE contact_records.role_kind WHEN 'holder' THEN 1 ELSE 2 END,
            contact_records.contact_record_key
        ) FILTER (
          WHERE NULLIF(btrim(contact_records.guest_email), '') IS NOT NULL
        )
      )[1] AS latest_email,
      (
        array_agg(
          contact_records.guest_birthdate
          ORDER BY
            contact_records.record_at DESC,
            CASE contact_records.role_kind WHEN 'holder' THEN 1 ELSE 2 END,
            contact_records.contact_record_key
        ) FILTER (
          WHERE contact_records.guest_birthdate IS NOT NULL
        )
      )[1] AS latest_birthdate,
      (
        array_agg(
          contact_records.lead_source
          ORDER BY
            contact_records.record_at DESC,
            CASE contact_records.role_kind WHEN 'holder' THEN 1 ELSE 2 END,
            contact_records.contact_record_key
        )
      )[1] AS latest_lead_source,
      bool_or(contact_records.role_kind = 'holder') AS has_holder_role,
      bool_or(contact_records.role_kind = 'companion') AS has_companion_role,
      max(contact_records.record_at) AS latest_contact_at
    FROM contact_records
    WHERE NOT contact_records.is_waitlist_suppressed
    GROUP BY
      contact_records.company_id,
      contact_records.customer_key
  ),
  presence_rollup AS (
    SELECT
      contact_records.company_id,
      contact_records.customer_key,
      count(*)::integer AS canonical_visit_count,
      (
        array_agg(
          contact_records.presence_date
          ORDER BY
            contact_records.presence_at DESC,
            contact_records.canonical_event_key DESC
        )
      )[1] AS last_visit_date,
      (
        array_agg(
          contact_records.presence_time
          ORDER BY
            contact_records.presence_at DESC,
            contact_records.canonical_event_key DESC
        )
      )[1] AS last_visit_time,
      max(contact_records.presence_at) AS last_visit_at
    FROM contact_records
    WHERE contact_records.is_canonical_presence
    GROUP BY
      contact_records.company_id,
      contact_records.customer_key
  ),
  normalized_imports AS (
    SELECT
      crm_leads.*,
      COALESCE(public.phone_identity_digits(crm_leads.phone_e164, crm_leads.phone, crm_leads.phone_country), public.phone_customer_identity_digits(NULL, crm_leads.phone_normalized, 'BR'), public.phone_customer_identity_digits(NULL, crm_leads.phone, crm_leads.phone_country)) AS canonical_phone,
      COALESCE(
        NULLIF(lower(btrim(crm_leads.email_normalized)), ''),
        NULLIF(lower(btrim(crm_leads.email)), '')
      ) AS canonical_email
    FROM public.crm_leads
    WHERE crm_leads.company_id = _company_id
  ),
  labeled_imports AS (
    SELECT
      normalized_imports.*,
      CASE
        WHEN NULLIF(btrim(normalized_imports.profile_customer_key), '') IS NOT NULL
          THEN public.canonical_crm_customer_key(normalized_imports.profile_customer_key)
        WHEN normalized_imports.canonical_phone IS NOT NULL
          THEN 'phone:' || normalized_imports.canonical_phone
        WHEN normalized_imports.canonical_email IS NOT NULL
          THEN 'email:' || normalized_imports.canonical_email
        ELSE 'contact:crm_lead:' || normalized_imports.id::text
      END AS customer_key,
      CASE
        WHEN normalized_imports.canonical_phone IS NOT NULL THEN 'phone'
        WHEN normalized_imports.canonical_email IS NOT NULL THEN 'email'
        ELSE 'contact'
      END AS identity_kind,
      CASE
        WHEN normalized_imports.canonical_phone IS NOT NULL THEN normalized_imports.canonical_phone
        WHEN normalized_imports.canonical_email IS NOT NULL THEN normalized_imports.canonical_email
        ELSE 'crm_lead:' || normalized_imports.id::text
      END AS identity_value
    FROM normalized_imports
  ),
  ranked_imports AS (
    SELECT
      labeled_imports.*,
      min(LEAST(labeled_imports.created_at, labeled_imports.imported_at)) OVER (
        PARTITION BY labeled_imports.company_id, labeled_imports.customer_key
      ) AS first_seen_at,
      row_number() OVER (
        PARTITION BY labeled_imports.company_id, labeled_imports.customer_key
        ORDER BY
          labeled_imports.imported_at DESC,
          labeled_imports.updated_at DESC,
          labeled_imports.id
      ) AS import_rank
    FROM labeled_imports
  ),
  latest_imports AS (
    SELECT *
    FROM ranked_imports
    WHERE ranked_imports.import_rank = 1
  ),
  identity_keys AS (
    SELECT
      visible_contact_rollup.company_id,
      visible_contact_rollup.customer_key
    FROM visible_contact_rollup

    UNION

    SELECT
      latest_imports.company_id,
      latest_imports.customer_key
    FROM latest_imports
  ),
  profiles_without_state AS (
    SELECT
      identity_keys.company_id,
      identity_keys.customer_key,
      COALESCE(visible_contact_rollup.identity_kind, latest_imports.identity_kind) AS identity_kind,
      COALESCE(visible_contact_rollup.identity_value, latest_imports.identity_value) AS identity_value,
      CASE
        WHEN latest_imports.source = 'manual_edit' THEN latest_imports.canonical_phone
        ELSE COALESCE(visible_contact_rollup.phone_normalized, latest_imports.canonical_phone)
      END AS phone_normalized,
      CASE
        WHEN latest_imports.source = 'manual_edit' THEN latest_imports.canonical_email
        ELSE COALESCE(visible_contact_rollup.email_normalized, latest_imports.canonical_email)
      END AS email_normalized,
      CASE
        WHEN latest_imports.source = 'manual_edit' THEN
          COALESCE(COALESCE(latest_imports.phone_e164, NULLIF(btrim(latest_imports.phone), '')), latest_imports.canonical_phone, '')
        WHEN latest_imports.updated_at > visible_contact_rollup.latest_contact_at THEN
          COALESCE(
            COALESCE(latest_imports.phone_e164, NULLIF(btrim(latest_imports.phone), '')),
            latest_imports.canonical_phone,
            visible_contact_rollup.display_phone,
            ''
          )
        ELSE
          COALESCE(
            visible_contact_rollup.display_phone,
            COALESCE(latest_imports.phone_e164, NULLIF(btrim(latest_imports.phone), '')),
            latest_imports.canonical_phone,
            ''
          )
      END AS display_phone,
      CASE
        WHEN latest_imports.source = 'manual_edit' OR latest_imports.updated_at > visible_contact_rollup.latest_contact_at THEN
          COALESCE(
            NULLIF(btrim(latest_imports.full_name), ''),
            visible_contact_rollup.latest_name,
            'Lead sem nome'
          )
        ELSE
          COALESCE(
            visible_contact_rollup.latest_name,
            NULLIF(btrim(latest_imports.full_name), ''),
            'Lead sem nome'
          )
      END AS latest_name,
      CASE
        WHEN latest_imports.source = 'manual_edit' THEN latest_imports.canonical_email
        WHEN latest_imports.updated_at > visible_contact_rollup.latest_contact_at THEN
          COALESCE(
            NULLIF(lower(btrim(latest_imports.email)), ''),
            latest_imports.canonical_email,
            visible_contact_rollup.latest_email
          )
        ELSE
          COALESCE(
            visible_contact_rollup.latest_email,
            NULLIF(lower(btrim(latest_imports.email)), ''),
            latest_imports.canonical_email
          )
      END AS latest_email,
      CASE
        WHEN latest_imports.source = 'manual_edit' THEN latest_imports.birthdate
        WHEN latest_imports.updated_at > visible_contact_rollup.latest_contact_at THEN
          COALESCE(latest_imports.birthdate, visible_contact_rollup.latest_birthdate)
        ELSE
          COALESCE(visible_contact_rollup.latest_birthdate, latest_imports.birthdate)
      END AS latest_birthdate,
      CASE
        WHEN contact_first_seen.first_seen_at IS NULL THEN latest_imports.first_seen_at
        WHEN latest_imports.first_seen_at IS NULL THEN contact_first_seen.first_seen_at
        ELSE LEAST(contact_first_seen.first_seen_at, latest_imports.first_seen_at)
      END AS first_seen_at,
      presence_rollup.last_visit_date,
      presence_rollup.last_visit_time,
      presence_rollup.last_visit_at,
      CASE
        WHEN visible_contact_rollup.customer_key IS NULL THEN 'imported'
        WHEN visible_contact_rollup.has_holder_role
          AND visible_contact_rollup.has_companion_role THEN 'mixed'
        ELSE visible_contact_rollup.latest_lead_source
      END AS source,
      COALESCE(presence_rollup.canonical_visit_count, 0)::integer AS canonical_visit_count,
      latest_imports.id AS crm_lead_id,
      latest_imports.notes AS crm_notes,
      latest_imports.imported_at AS crm_imported_at,
      latest_imports.imported_by_user_id AS crm_imported_by_user_id,
      latest_imports.import_filename AS crm_import_filename,
      visible_contact_rollup.customer_key IS NULL AS is_import_only
    FROM identity_keys
    LEFT JOIN contact_first_seen
      ON contact_first_seen.company_id = identity_keys.company_id
     AND contact_first_seen.customer_key = identity_keys.customer_key
    LEFT JOIN visible_contact_rollup
      ON visible_contact_rollup.company_id = identity_keys.company_id
     AND visible_contact_rollup.customer_key = identity_keys.customer_key
    LEFT JOIN presence_rollup
      ON presence_rollup.company_id = identity_keys.company_id
     AND presence_rollup.customer_key = identity_keys.customer_key
    LEFT JOIN latest_imports
      ON latest_imports.company_id = identity_keys.company_id
     AND latest_imports.customer_key = identity_keys.customer_key
  ),
  profiles_with_state AS (
    SELECT
      profiles_without_state.*,
      public._crm_phone_state_code(profiles_without_state.phone_normalized) AS state_code
    FROM profiles_without_state
  )
  SELECT
    profiles_with_state.company_id,
    profiles_with_state.customer_key,
    profiles_with_state.identity_kind,
    profiles_with_state.identity_value,
    profiles_with_state.phone_normalized,
    profiles_with_state.email_normalized,
    profiles_with_state.display_phone,
    profiles_with_state.latest_name,
    profiles_with_state.latest_email,
    profiles_with_state.latest_birthdate,
    profiles_with_state.first_seen_at,
    profiles_with_state.last_visit_date,
    profiles_with_state.last_visit_time,
    profiles_with_state.last_visit_at,
    profiles_with_state.state_code,
    public._crm_state_name(profiles_with_state.state_code) AS state_name,
    profiles_with_state.source,
    profiles_with_state.canonical_visit_count,
    profiles_with_state.crm_lead_id,
    profiles_with_state.crm_notes,
    profiles_with_state.crm_imported_at,
    profiles_with_state.crm_imported_by_user_id,
    profiles_with_state.crm_import_filename,
    profiles_with_state.is_import_only
  FROM profiles_with_state;
$function$;

CREATE OR REPLACE FUNCTION public.get_crm_leads_page(_company_id uuid, _page integer DEFAULT 1, _page_size integer DEFAULT 25, _search text DEFAULT NULL::text, _created_from date DEFAULT NULL::date, _created_to date DEFAULT NULL::date, _state_code text DEFAULT NULL::text, _birthday_month integer DEFAULT NULL::integer, _min_visits integer DEFAULT NULL::integer, _max_visits integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _effective_state_code text := NULLIF(upper(btrim(COALESCE(_state_code, ''))), '');
  _search_text text := NULLIF(lower(btrim(COALESCE(_search, ''))), '');
  _search_digits text := NULLIF(regexp_replace(COALESCE(_search, ''), '\D', '', 'g'), '');
  _offset bigint;
  _result jsonb;
BEGIN
  IF _company_id IS NULL THEN
    RAISE EXCEPTION 'company_id e obrigatorio.' USING ERRCODE = '22023';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.role() IS DISTINCT FROM 'authenticated' OR public.effective_auth_uid(_company_id) IS NULL THEN
      RAISE EXCEPTION 'Nao autorizado.' USING ERRCODE = '42501';
    END IF;

    IF NOT public.has_company_panel_permission(public.effective_auth_uid(_company_id), _company_id, 'leads_view') THEN
      RAISE EXCEPTION 'Sem permissao para visualizar leads.' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _page IS NULL OR _page < 1 THEN
    RAISE EXCEPTION 'page deve ser maior ou igual a 1.' USING ERRCODE = '22023';
  END IF;

  IF _page_size IS NULL OR _page_size < 1 OR _page_size > 100 THEN
    RAISE EXCEPTION 'page_size deve estar entre 1 e 100.' USING ERRCODE = '22023';
  END IF;

  IF _search_text IS NOT NULL AND char_length(_search_text) > 200 THEN
    RAISE EXCEPTION 'search nao pode ultrapassar 200 caracteres.' USING ERRCODE = '22023';
  END IF;

  IF _created_from IS NOT NULL
    AND _created_to IS NOT NULL
    AND _created_to < _created_from THEN
    RAISE EXCEPTION 'Intervalo de criacao invalido.' USING ERRCODE = '22023';
  END IF;

  IF _effective_state_code = 'ALL' THEN
    _effective_state_code := NULL;
  END IF;

  IF _effective_state_code IS NOT NULL
    AND _effective_state_code <> 'UNKNOWN'
    AND _effective_state_code NOT IN (
      'AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG',
      'PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'
    ) THEN
    RAISE EXCEPTION 'state_code invalido.' USING ERRCODE = '22023';
  END IF;

  IF _birthday_month IS NOT NULL
    AND (_birthday_month < 1 OR _birthday_month > 12) THEN
    RAISE EXCEPTION 'birthday_month deve estar entre 1 e 12.' USING ERRCODE = '22023';
  END IF;

  IF _min_visits IS NOT NULL AND (_min_visits < 0 OR _min_visits > 1000000) THEN
    RAISE EXCEPTION 'min_visits invalido.' USING ERRCODE = '22023';
  END IF;

  IF _max_visits IS NOT NULL AND (_max_visits < 0 OR _max_visits > 1000000) THEN
    RAISE EXCEPTION 'max_visits invalido.' USING ERRCODE = '22023';
  END IF;

  IF _min_visits IS NOT NULL
    AND _max_visits IS NOT NULL
    AND _max_visits < _min_visits THEN
    RAISE EXCEPTION 'max_visits deve ser maior ou igual a min_visits.' USING ERRCODE = '22023';
  END IF;

  _offset := (_page::bigint - 1) * _page_size::bigint;

  WITH profiles AS MATERIALIZED (
    SELECT *
    FROM public._get_crm_lead_profiles(_company_id)
  ),
  filtered_profiles AS MATERIALIZED (
    SELECT profiles.*
    FROM profiles
    WHERE (
        _search_text IS NULL
        OR position(_search_text IN lower(COALESCE(profiles.latest_name, ''))) > 0
        OR position(_search_text IN lower(COALESCE(profiles.latest_email, ''))) > 0
        OR position(_search_text IN lower(COALESCE(profiles.display_phone, ''))) > 0
        OR position(_search_text IN lower(profiles.customer_key)) > 0
        OR (
          _search_digits IS NOT NULL
          AND (
            position(_search_digits IN COALESCE(profiles.phone_normalized, '')) > 0
            OR position(
              _search_digits
              IN regexp_replace(COALESCE(profiles.display_phone, ''), '\D', '', 'g')
            ) > 0
          )
        )
      )
      AND (
        _created_from IS NULL
        OR (profiles.first_seen_at AT TIME ZONE 'America/Fortaleza')::date >= _created_from
      )
      AND (
        _created_to IS NULL
        OR (profiles.first_seen_at AT TIME ZONE 'America/Fortaleza')::date <= _created_to
      )
      AND (
        _effective_state_code IS NULL
        OR (
          _effective_state_code = 'UNKNOWN'
          AND profiles.state_code IS NULL
        )
        OR profiles.state_code = _effective_state_code
      )
      AND (
        _birthday_month IS NULL
        OR extract(month FROM profiles.latest_birthdate)::integer = _birthday_month
      )
      AND (
        _min_visits IS NULL
        OR profiles.canonical_visit_count >= _min_visits
      )
      AND (
        _max_visits IS NULL
        OR profiles.canonical_visit_count <= _max_visits
      )
  ),
  paged_profiles AS (
    SELECT filtered_profiles.*
    FROM filtered_profiles
    ORDER BY
      filtered_profiles.canonical_visit_count DESC,
      filtered_profiles.first_seen_at DESC,
      filtered_profiles.customer_key
    LIMIT _page_size
    OFFSET _offset
  ),
  total_stats AS (
    SELECT
      count(*)::integer AS total_leads,
      COALESCE(sum(profiles.canonical_visit_count), 0)::integer AS total_canonical_visits,
      count(*) FILTER (WHERE profiles.is_import_only)::integer AS total_import_only_leads
    FROM profiles
  ),
  filtered_stats AS (
    SELECT
      count(*)::integer AS filtered_leads,
      COALESCE(sum(filtered_profiles.canonical_visit_count), 0)::integer
        AS filtered_canonical_visits,
      count(*) FILTER (WHERE filtered_profiles.is_import_only)::integer
        AS filtered_import_only_leads
    FROM filtered_profiles
  )
  SELECT jsonb_build_object(
    'leads', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'customer_key', paged_profiles.customer_key,
            'identity_kind', paged_profiles.identity_kind,
            'phone_normalized', paged_profiles.phone_normalized,
            'display_phone', paged_profiles.display_phone,
            'latest_name', paged_profiles.latest_name,
            'latest_email', paged_profiles.latest_email,
            'latest_birthdate', paged_profiles.latest_birthdate,
            'first_seen_at', paged_profiles.first_seen_at,
            'last_visit_date', paged_profiles.last_visit_date,
            'last_visit_time', paged_profiles.last_visit_time,
            'state_code', paged_profiles.state_code,
            'state_name', paged_profiles.state_name,
            'source', paged_profiles.source,
            'canonical_visit_count', paged_profiles.canonical_visit_count,
            'is_import_only', paged_profiles.is_import_only,
            'crm_lead', CASE
              WHEN paged_profiles.crm_lead_id IS NULL THEN NULL
              ELSE jsonb_build_object(
                'id', paged_profiles.crm_lead_id,
                'notes', paged_profiles.crm_notes,
                'imported_at', paged_profiles.crm_imported_at,
                'imported_by_user_id', paged_profiles.crm_imported_by_user_id,
                'import_filename', paged_profiles.crm_import_filename
              )
            END
          )
          ORDER BY
            paged_profiles.canonical_visit_count DESC,
            paged_profiles.first_seen_at DESC,
            paged_profiles.customer_key
        )
        FROM paged_profiles
      ),
      '[]'::jsonb
    ),
    'states', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'code', state_options.state_code,
            'name', state_options.state_name,
            'leads', state_options.leads
          )
          ORDER BY state_options.state_name, state_options.state_code
        )
        FROM (
          SELECT
            profiles.state_code,
            min(profiles.state_name) AS state_name,
            count(*)::integer AS leads
          FROM profiles
          WHERE profiles.state_code IS NOT NULL
          GROUP BY profiles.state_code
        ) AS state_options
      ),
      '[]'::jsonb
    ),
    'meta', jsonb_build_object(
      'page', _page,
      'page_size', _page_size,
      'total_leads', total_stats.total_leads,
      'filtered_leads', filtered_stats.filtered_leads,
      'total_canonical_visits', total_stats.total_canonical_visits,
      'filtered_canonical_visits', filtered_stats.filtered_canonical_visits,
      'total_import_only_leads', total_stats.total_import_only_leads,
      'filtered_import_only_leads', filtered_stats.filtered_import_only_leads,
      'total_records',
        total_stats.total_canonical_visits + total_stats.total_import_only_leads,
      'filtered_records',
        filtered_stats.filtered_canonical_visits + filtered_stats.filtered_import_only_leads,
      'generated_at', now()
    )
  )
  INTO _result
  FROM total_stats
  CROSS JOIN filtered_stats;

  RETURN _result;
END;
$function$;

CREATE OR REPLACE FUNCTION public._get_customer_canonical_visit_events(_company_id uuid, _through_date date DEFAULT NULL::date, _include_companions boolean DEFAULT true)
 RETURNS TABLE(company_id uuid, customer_key text, identity_kind text, identity_value text, canonical_event_key text, contact_record_key text, visit_id uuid, contact_id uuid, visit_origin text, lead_source text, role_kind text, record_date date, record_time time without time zone, record_at timestamp with time zone, presence_date date, presence_time time without time zone, presence_at timestamp with time zone, contact_created_at timestamp with time zone, guest_name text, guest_phone text, guest_email text, guest_birthdate date, phone_normalized text, email_normalized text, party_size integer, status text, normalized_status text, occasion text, origin_waitlist_id uuid, came_from_waitlist boolean, reservation_holder_name text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    contact_records.company_id,
    contact_records.customer_key,
    contact_records.identity_kind,
    contact_records.identity_value,
    contact_records.canonical_event_key,
    contact_records.contact_record_key,
    contact_records.visit_id,
    contact_records.contact_id,
    contact_records.visit_origin,
    contact_records.lead_source,
    contact_records.role_kind,
    contact_records.record_date,
    contact_records.record_time,
    contact_records.record_at,
    contact_records.presence_date,
    contact_records.presence_time,
    contact_records.presence_at,
    contact_records.contact_created_at,
    contact_records.guest_name,
    contact_records.guest_phone,
    contact_records.guest_email,
    contact_records.guest_birthdate,
    contact_records.phone_normalized,
    contact_records.email_normalized,
    contact_records.party_size,
    contact_records.status,
    contact_records.normalized_status,
    contact_records.occasion,
    contact_records.origin_waitlist_id,
    contact_records.came_from_waitlist,
    contact_records.reservation_holder_name
  FROM public._get_crm_contact_records(_company_id) AS contact_records
  WHERE contact_records.is_canonical_presence
    AND (
      COALESCE(_include_companions, true)
      OR contact_records.role_kind = 'holder'
    )
    AND (
      _through_date IS NULL
      OR contact_records.presence_date <= _through_date
    );
$function$;

CREATE OR REPLACE FUNCTION public._get_crm_relationship_reservations(_company_id uuid, _customer_key text)
 RETURNS TABLE(id uuid, date date, "time" time without time zone, party_size integer, checked_in_party_size integer, status text, source text, occasion text, relationship_role text, holder_name text, is_upcoming boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH contacts AS MATERIALIZED (
    SELECT DISTINCT ON (c.visit_id) c.visit_id, c.role_kind
    FROM public._get_crm_contact_records(_company_id) c
    WHERE c.company_id = _company_id AND c.customer_key = _customer_key AND c.visit_origin = 'reservation'
    ORDER BY c.visit_id, CASE c.role_kind WHEN 'holder' THEN 0 ELSE 1 END, c.contact_record_key
  ), normalized AS (
    SELECT r.id, r.date, r.time, r.party_size, r.checked_in_party_size,
      CASE
        WHEN lower(btrim(r.status)) IN ('checked_in','completed') THEN 'checked_in'
        WHEN lower(btrim(r.status)) IN ('no_show','no-show') THEN 'no-show'
        WHEN lower(btrim(r.status)) IN ('pending_payment','cancelled','payment_expired','payment_cancelled','paid_after_expiration') THEN lower(btrim(r.status))
        ELSE 'confirmed'
      END AS status,
      r.source, r.occasion, c.role_kind AS relationship_role, r.guest_name AS holder_name
    FROM contacts c JOIN public.reservations r ON r.id = c.visit_id AND r.company_id = _company_id
  )
  SELECT n.*, n.status IN ('confirmed','pending_payment')
    AND (n.date + n.time) AT TIME ZONE public._company_report_time_zone(_company_id) >= now() AS is_upcoming
  FROM normalized n;
$function$;

CREATE OR REPLACE FUNCTION public.get_company_crm_relationship(_company_id uuid, _customer_key text, _section text DEFAULT 'summary'::text, _page integer DEFAULT 1, _page_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _key text;
  _can_reservations boolean;
  _can_payments boolean;
  _can_messages boolean;
  _service boolean := auth.role() = 'service_role';
  _summary jsonb;
  _rows jsonb := '[]'::jsonb;
  _total bigint := 0;
  _effective_page integer := 1;
  _phone text;
BEGIN
  -- Permission helpers resolve support impersonation and its exact company
  -- scope. Authorize before inspecting any caller-controlled customer identity.
  IF NOT COALESCE(_service, false) THEN
    IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Nao autorizado.' USING ERRCODE = '42501';
    END IF;
    IF public.has_company_panel_permission(auth.uid(), _company_id, 'leads_view') IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'Sem permissao para visualizar clientes.' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF _company_id IS NULL OR NULLIF(btrim(_customer_key), '') IS NULL OR char_length(_customer_key) > 500 THEN
    RAISE EXCEPTION 'Cliente invalido.' USING ERRCODE = '22023';
  END IF;
  IF _section IS NULL OR _section NOT IN ('summary','reservations','payments','messages')
    OR _page IS NULL OR _page < 1 OR _page > 1000000 OR _page_size IS NULL OR _page_size < 1 OR _page_size > 100 THEN
    RAISE EXCEPTION 'Parametros de consulta invalidos.' USING ERRCODE = '22023';
  END IF;

  _key := public.canonical_crm_customer_key(_customer_key);
  IF NOT EXISTS (SELECT 1 FROM public._get_crm_lead_profiles(_company_id) p WHERE p.customer_key = _key) THEN
    RAISE EXCEPTION 'Cliente nao encontrado nesta unidade.' USING ERRCODE = 'P0002';
  END IF;

  _can_reservations := COALESCE(_service, false) OR COALESCE(public.has_company_panel_permission(auth.uid(), _company_id, 'reservations_view'),false);
  _can_payments := _can_reservations AND (COALESCE(_service, false)
    OR COALESCE(public.has_role(auth.uid(), 'superadmin'),false) OR COALESCE(public.has_role_in_company(auth.uid(), 'admin', _company_id),false));
  _can_messages := COALESCE(_service, false) OR COALESCE(public.has_company_panel_permission(auth.uid(), _company_id, 'automations_view'),false);
  IF (_section = 'reservations' AND NOT _can_reservations)
    OR (_section = 'payments' AND NOT _can_payments) OR (_section = 'messages' AND NOT _can_messages) THEN
    RAISE EXCEPTION 'Sem permissao para esta parte do perfil.' USING ERRCODE = '42501';
  END IF;

  IF _can_reservations THEN
    SELECT jsonb_build_object(
      'upcoming_count', count(*) FILTER (WHERE r.is_upcoming),
      'reservation_count', count(*),
      'cancelled_count', count(*) FILTER (WHERE r.status = 'cancelled'),
      'no_show_count', count(*) FILTER (WHERE r.status = 'no-show')
    ) INTO _summary FROM public._get_crm_relationship_reservations(_company_id, _key) r;
  ELSE
    _summary := jsonb_build_object('upcoming_count',NULL,'reservation_count',NULL,'cancelled_count',NULL,'no_show_count',NULL);
  END IF;

  IF _section = 'reservations' THEN
    WITH all_rows AS MATERIALIZED (
      SELECT r.* FROM public._get_crm_relationship_reservations(_company_id, _key) r
    ), totals AS (SELECT count(*) AS total FROM all_rows), bounds AS (
      SELECT total, least(_page, greatest(1, ceil(total::numeric / _page_size)::integer)) AS page FROM totals
    ), paged AS (
      SELECT a.* FROM all_rows a
      ORDER BY a.is_upcoming DESC,
        CASE WHEN a.is_upcoming THEN a.date END ASC, CASE WHEN a.is_upcoming THEN a.time END ASC,
        a.date DESC, a.time DESC, a.id DESC
      LIMIT _page_size OFFSET (SELECT (page-1)*_page_size FROM bounds)
    )
    SELECT b.total,b.page,COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.is_upcoming DESC,
      CASE WHEN p.is_upcoming THEN p.date END ASC, CASE WHEN p.is_upcoming THEN p.time END ASC,
      p.date DESC,p.time DESC,p.id DESC) FROM paged p),'[]'::jsonb)
    INTO _total,_effective_page,_rows FROM bounds b;
  ELSIF _section = 'payments' THEN
    -- A companion's participation is not their payment or personal spend.
    WITH holder_reservations AS MATERIALIZED (
      SELECT r.id,r.date,r.time FROM public._get_crm_relationship_reservations(_company_id, _key) r
      WHERE r.relationship_role = 'holder'
    ), all_rows AS MATERIALIZED (
      SELECT p.id,p.reservation_id,r.date AS reservation_date,r.time AS reservation_time,
        p.status,p.billing_type,p.base_amount,p.charged_amount,p.paid_at,p.created_at,
        NULL::timestamptz AS refunded_at
      FROM holder_reservations r JOIN public.reservation_payments p ON p.reservation_id=r.id AND p.company_id=_company_id
    ), totals AS (SELECT count(*) AS total FROM all_rows), bounds AS (
      SELECT total,least(_page,greatest(1,ceil(total::numeric/_page_size)::integer)) AS page FROM totals
    ), paged AS (
      SELECT a.* FROM all_rows a ORDER BY a.created_at DESC,a.id DESC
      LIMIT _page_size OFFSET (SELECT (page-1)*_page_size FROM bounds)
    )
    SELECT b.total,b.page,COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM paged p),'[]'::jsonb)
    INTO _total,_effective_page,_rows FROM bounds b;
  ELSIF _section = 'messages' THEN
    -- Match the canonical recipient, never the name, phone suffix, or another
    -- guest's messages merely because they accompanied the same reservation.
    _phone := CASE WHEN _key LIKE 'phone:%' THEN substring(_key FROM 7) ELSE NULL END;
    WITH all_rows AS MATERIALIZED (
      SELECT 'evolution:'||l.id AS id,'evolution'::text AS channel,l.type,l.status,l.created_at,
        l.reservation_id,'log'::text AS record_source,NULL::text AS provider_status,
        left(l.message,240) AS message_preview,NULL::text AS template_name
      FROM public.whatsapp_message_logs l
      WHERE l.company_id=_company_id AND _phone IS NOT NULL
        AND public.phone_customer_identity_digits(NULL,l.phone,'BR')=_phone
      UNION ALL
      SELECT 'pluguechat:'||l.id,'pluguechat_official',l.type,l.status,l.created_at,
        l.reservation_id,'log',l.provider_status,NULL::text,l.template_name
      FROM public.pluguechat_message_logs l
      WHERE l.company_id=_company_id AND _phone IS NOT NULL
        AND public.phone_customer_identity_digits(NULL,l.phone,'BR')=_phone
    ), totals AS (SELECT count(*) AS total FROM all_rows), bounds AS (
      SELECT total,least(_page,greatest(1,ceil(total::numeric/_page_size)::integer)) AS page FROM totals
    ), paged AS (
      SELECT a.* FROM all_rows a ORDER BY a.created_at DESC,a.id DESC
      LIMIT _page_size OFFSET (SELECT (page-1)*_page_size FROM bounds)
    )
    SELECT b.total,b.page,COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM paged p),'[]'::jsonb)
    INTO _total,_effective_page,_rows FROM bounds b;
  END IF;

  RETURN jsonb_build_object('company_id',_company_id,'customer_key',_customer_key,'canonical_customer_key',_key,
    'section',_section,'page',_effective_page,'page_size',_page_size,'total',_total,'rows',_rows,
    'capabilities',jsonb_build_object('reservations',_can_reservations,'payments',_can_payments,'messages',_can_messages),
    'summary',_summary,'generated_at',now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_crm_lead_presence_history(_company_id uuid, _customer_key text, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _effective_customer_key text := public.canonical_crm_customer_key(COALESCE(_customer_key, ''));
  _identity_kind text;
  _identity_value text;
  _offset bigint;
  _result jsonb;
BEGIN
  IF _company_id IS NULL THEN
    RAISE EXCEPTION 'company_id e obrigatorio.' USING ERRCODE = '22023';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.role() IS DISTINCT FROM 'authenticated' OR public.effective_auth_uid(_company_id) IS NULL THEN
      RAISE EXCEPTION 'Nao autorizado.' USING ERRCODE = '42501';
    END IF;

    IF NOT public.has_company_panel_permission(public.effective_auth_uid(_company_id), _company_id, 'leads_view') THEN
      RAISE EXCEPTION 'Sem permissao para visualizar leads.' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _effective_customer_key = '' OR char_length(_effective_customer_key) > 400 THEN
    RAISE EXCEPTION 'customer_key invalido.' USING ERRCODE = '22023';
  END IF;

  IF _effective_customer_key LIKE 'phone:%' THEN
    _identity_kind := 'phone';
    _identity_value := substring(_effective_customer_key FROM 7);

    IF _identity_value !~ '^[0-9]+$'
      OR (
        public.normalize_whatsapp_phone('+' || _identity_value) IS DISTINCT FROM _identity_value
        AND NOT EXISTS (
          SELECT 1 FROM public._get_crm_contact_records(_company_id) AS legacy_contact
          WHERE legacy_contact.customer_key = _effective_customer_key
        )
      ) THEN
      RAISE EXCEPTION 'customer_key de telefone invalido.' USING ERRCODE = '22023';
    END IF;
  ELSIF _effective_customer_key LIKE 'email:%' THEN
    _identity_kind := 'email';
    _identity_value := substring(_effective_customer_key FROM 7);

    IF _identity_value = ''
      OR char_length(_identity_value) > 320
      OR lower(btrim(_identity_value)) IS DISTINCT FROM _identity_value THEN
      RAISE EXCEPTION 'customer_key de email invalido.' USING ERRCODE = '22023';
    END IF;
  ELSIF _effective_customer_key ~
    '^contact:(reservation_holder|reservation_companion|waitlist_holder|waitlist_companion|crm_lead):[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    _identity_kind := 'contact';
    _identity_value := substring(_effective_customer_key FROM 9);
  ELSE
    RAISE EXCEPTION 'customer_key invalido.' USING ERRCODE = '22023';
  END IF;

  IF _page IS NULL OR _page < 1 THEN
    RAISE EXCEPTION 'page deve ser maior ou igual a 1.' USING ERRCODE = '22023';
  END IF;

  IF _page_size IS NULL OR _page_size < 1 OR _page_size > 100 THEN
    RAISE EXCEPTION 'page_size deve estar entre 1 e 100.' USING ERRCODE = '22023';
  END IF;

  _offset := (_page::bigint - 1) * _page_size::bigint;

  WITH customer_visits AS MATERIALIZED (
    SELECT canonical_visits.*
    FROM public._get_customer_canonical_visit_events(
      _company_id,
      NULL,
      true
    ) AS canonical_visits
    WHERE canonical_visits.customer_key = _effective_customer_key
  ),
  paged_visits AS (
    SELECT customer_visits.*
    FROM customer_visits
    ORDER BY
      customer_visits.presence_at DESC,
      customer_visits.canonical_event_key DESC
    LIMIT _page_size
    OFFSET _offset
  )
  SELECT jsonb_build_object(
    'customer_key', _effective_customer_key,
    'identity_kind', _identity_kind,
    'identity_value', _identity_value,
    'phone_normalized', CASE
      WHEN _identity_kind = 'phone' THEN _identity_value
      ELSE NULL
    END,
    'visits', COALESCE(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', paged_visits.canonical_event_key,
            'visit_id', paged_visits.visit_id,
            'created_at', paged_visits.contact_created_at,
            'date', paged_visits.presence_date,
            'time', paged_visits.presence_time,
            'party_size', paged_visits.party_size,
            'status', paged_visits.status,
            'occasion', paged_visits.occasion,
            'lead_source', paged_visits.lead_source,
            'visit_origin', paged_visits.visit_origin,
            'origin_waitlist_id', paged_visits.origin_waitlist_id,
            'came_from_waitlist', paged_visits.came_from_waitlist,
            'reservation_holder_name', paged_visits.reservation_holder_name
          )
          ORDER BY
            paged_visits.presence_at DESC,
            paged_visits.canonical_event_key DESC
        )
        FROM paged_visits
      ),
      '[]'::jsonb
    ),
    'meta', jsonb_build_object(
      'page', _page,
      'page_size', _page_size,
      'total_visits', (SELECT count(*)::integer FROM customer_visits),
      'generated_at', now()
    )
  )
  INTO _result;

  RETURN _result;
END;
$function$;
